{
  "concepts_used": ["GC-0001", "GC-0002", "GC-0004", "GC-0008", "GC-0009", "GC-0010", "GC-0011", "GC-0012", "GC-0017", "GC-0019", "GC-0021", "GC-0038", "GC-0168"],
